import{_ as t,c as a,o as i,ag as l}from"./chunks/framework.DPDPlp3K.js";const b=JSON.parse('{"title":"环境信息管理系统","description":"","frontmatter":{"layout":"home","hero":{"name":"环境信息管理系统","text":"集中管理各系统开发与测试环境信息","tagline":"高效管理各环境的数据库、Redis等配置信息","actions":[{"theme":"brand","text":"风控决策系统","link":"/risk-control/"},{"theme":"alt","text":"资信系统","link":"/credit-system/"}]},"features":[{"title":"集中管理","details":"统一管理各系统在不同环境的配置信息"},{"title":"快速查找","details":"分类清晰，便于快速查找所需环境信息"},{"title":"搜索功能","details":"支持全文搜索，快速定位所需环境信息和配置"},{"title":"安全可靠","details":"仅限内部使用，确保敏感信息安全"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function r(n,e,d,s,c,h){return i(),a("div",null,e[0]||(e[0]=[l('<h1 id="环境信息管理系统" tabindex="-1">环境信息管理系统 <a class="header-anchor" href="#环境信息管理系统" aria-label="Permalink to &quot;环境信息管理系统&quot;">​</a></h1><p>本系统用于管理各个业务系统在不同环境下的数据库、Redis等配置信息，包括但不限于以下系统：</p><h2 id="系统列表" tabindex="-1">系统列表 <a class="header-anchor" href="#系统列表" aria-label="Permalink to &quot;系统列表&quot;">​</a></h2><ul><li><a href="/risk-control/">风控决策系统</a></li><li><a href="/credit-system/">资信系统</a></li></ul><h2 id="环境说明" tabindex="-1">环境说明 <a class="header-anchor" href="#环境说明" aria-label="Permalink to &quot;环境说明&quot;">​</a></h2><ul><li><strong>开发环境</strong>：供开发人员日常开发使用</li><li><strong>SIT环境</strong>：系统集成测试环境</li><li><strong>UAT环境</strong>：用户验收测试环境</li><li><strong>PRE环境</strong>：预生产环境</li><li><strong>PRD环境</strong>：生产环境</li></ul><h2 id="搜索使用说明" tabindex="-1">搜索使用说明 <a class="header-anchor" href="#搜索使用说明" aria-label="Permalink to &quot;搜索使用说明&quot;">​</a></h2><p>本系统提供强大的搜索功能，帮助您快速定位需要的环境信息：</p><ol><li>点击页面右上角的<strong>搜索图标</strong>或使用快捷键 <kbd>Ctrl</kbd> + <kbd>K</kbd>（Windows/Linux）或 <kbd>⌘</kbd> + <kbd>K</kbd>（Mac）</li><li>在搜索框中输入关键词，如系统名称、环境名称、数据库类型等</li><li>支持多关键词组合搜索，如&quot;风控 MySQL SIT1&quot;</li><li>支持模糊搜索，输入部分关键词也能找到相关结果</li><li>搜索结果会显示匹配页面的标题和简要描述</li></ol><h3 id="搜索示例" tabindex="-1">搜索示例 <a class="header-anchor" href="#搜索示例" aria-label="Permalink to &quot;搜索示例&quot;">​</a></h3><ul><li>查找特定系统环境：<code>风控 开发环境1</code></li><li>查找特定数据库信息：<code>资信 MongoDB</code></li><li>查找Redis配置：<code>Redis SIT</code></li><li>查找测试账号：<code>测试账号 admin</code></li></ul><blockquote><p><strong>提示</strong>：为了提高搜索效率，建议使用具体且唯一的关键词</p></blockquote><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><ul><li>可通过页面顶部的<strong>搜索功能</strong>查找特定环境信息，如数据库地址、账号等</li><li>支持中文搜索，输入关键词即可快速定位相关信息</li></ul>',14)]))}const k=t(o,[["render",r]]);export{b as __pageData,k as default};
